import { z } from 'zod';
import {
  GuidanceSelectionSchema,
  type GuidanceSelection,
} from '../types/guidance';
import { stringFlag, type ParsedFlags } from './flags';

export const GUIDANCE_FLAG_SPEC = {
  guidance: { takesValue: true },
  'exclude-guidance': { takesValue: true },
};

export const guidanceSelectionFromFlags = (
  flags: ParsedFlags,
): GuidanceSelection => {
  const exclusions = stringFlag(flags, 'exclude-guidance');
  let excludedIds: unknown = [];
  if (exclusions !== undefined) {
    try {
      excludedIds = JSON.parse(exclusions);
    } catch {
      throw new z.ZodError([
        {
          code: 'custom',
          path: ['exclude-guidance'],
          message:
            '--exclude-guidance must be a JSON array of saved context IDs',
        },
      ]);
    }
  }
  return GuidanceSelectionSchema.parse({
    mode: stringFlag(flags, 'guidance') ?? 'auto',
    excludedIds,
  });
};
